STRAINT [FK__TahlilSon__Tahli__4E88ABD4]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/Table[@Name='TahlilSonuclari' and @Schema='dbo']/ForeignKey[@Name='FK__TahlilSon__Tahli__4E88ABD4']","object_type":"ForeignKey"}},{"cell_type":"markdown","source":["# [FK__Yatislar__HastaI__3B75D760]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/Table[@Name='Yatislar' and @Schema='dbo']/ForeignKey[@Name='FK__Yatislar__HastaI__3B75D760']","object_type":"ForeignKey"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["ALTER TABLE [dbo].[Yatislar]  WITH CHECK ADD  CONSTRAINT [FK__Yatislar__HastaI__3B75D760] FOREIGN KEY([hasta_ID])\r\nREFERENCES [dbo].[Hastalar] ([hasta_id])\r\n","GO\r\n","ALTER TABLE [dbo].[Yatislar] CHECK CONSTRAINT [FK__Yatislar__HastaI__3B75D760]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/Table[@Name='Yatislar' and @Schema='dbo']/ForeignKey[@Name='FK__Yatislar__HastaI__3B75D760']","object_type":"ForeignKey"}},{"cell_type":"markdown","source":["# [FK__Yatislar__OdaID__3C69FB99]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/Table[@Name='Yatislar' and @Schema='dbo']/ForeignKey[@Name='FK__Yatislar__OdaID__3C69FB99']","object_type":"ForeignKey"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["ALTER TABLE [dbo].[Yatislar]  WITH CHECK ADD  CONSTRAINT [FK__Yatislar__OdaID__3C69FB99] FOREIGN KEY([oda_ID])\r\nREFERENCES [dbo].[Odalar] ([oda_id])\r\n","GO\r\n","ALTER TABLE [dbo].[Yatislar] CHECK CONSTRAINT [FK__Yatislar__OdaID__3C69FB99]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/Table[@Name='Yatislar' and @Schema='dbo']/ForeignKey[@Name='FK__Yatislar__OdaID__3C69FB99']","object_type":"ForeignKey"}},{"cell_type":"markdown","source":["# [dbo].[sp_AktifMuayeneleriGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_AktifMuayeneleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_AktifMuayeneleriGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE   PROCEDURE [dbo].[sp_AktifMuayeneleriGetir] @kullanici_id INT AS BEGIN DECLARE @doktor_id INT = (SELECT TOP 1 doktor_id FROM Doktorlar WHERE kullanici_ID = @kullanici_id); SELECT r.randevu_id AS [Kayıt No], k.tc_no AS [TC Kimlik], h.hastalar_ad_soyad AS [Hasta Adı Soyadı], CONVERT(VARCHAR(16), r.randevu_tarihi, 120) AS [Randevu Zamanı] FROM Randevular r INNER JOIN Hastalar h ON r.hasta_ID = h.hasta_id INNER JOIN Kullanicilar k ON h.kullanici_ID = k.kullanici_id WHERE r.randevu_durum = 0 AND r.doktor_ID = @doktor_id AND CAST(r.randevu_tarihi AS DATE) = CAST(GETDATE() AS DATE) ORDER BY r.randevu_tarihi ASC; END\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_AktifMuayeneleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_AktifYatislariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_AktifYatislariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_AktifYatislariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- 4. Aktif Yatan Hastaları Getir (Formun sağ tarafındaki liste için)\r\nCREATE   PROCEDURE [dbo].[sp_AktifYatislariGetir]\r\nAS\r\nBEGIN\r\n    SELECT \r\n        h.hastalar_ad_soyad AS [Yatan Hasta],\r\n        y.oda_ID AS [Oda No],\r\n        CONVERT(VARCHAR(10), y.yatis_tarihi, 104) AS [Yatış Tarihi]\r\n    FROM Yatislar y\r\n    INNER JOIN Hastalar h ON y.hasta_ID = h.hasta_id\r\n    WHERE y.cikis_tarihi IS NULL\r\n    ORDER BY y.yatis_tarihi DESC;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_AktifYatislariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_BekleyenTahlilleriGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_BekleyenTahlilleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_BekleyenTahlilleriGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","\nCREATE PROCEDURE [dbo].[sp_BekleyenTahlilleriGetir]\nAS\nBEGIN\n    SELECT \n        ts.sonuc_id,\n        k.ad_soyad AS HastaAdi,\n        t.tahlil_adi AS TahlilAdi,\n        ts.tahlil_sonuclari_tarih AS IstenmeTarihi,\n        d_k.ad_soyad AS DoktorAdi,\n        t.referans_araligi AS ReferansAraligi\n    FROM TahlilSonuclari ts\n    JOIN Kullanicilar k ON ts.hasta_ID = k.kullanici_id\n    JOIN Tahliller t ON ts.tahlil_ID = t.tahlil_id\n    JOIN Doktorlar d ON ts.doktor_ID = d.doktor_id\n    JOIN Kullanicilar d_k ON d.kullanici_ID = d_k.kullanici_id\n    WHERE ts.sonuc_degeri = 'Sonuç Bekleniyor...'\n    ORDER BY ts.tahlil_sonuclari_tarih ASC;\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_BekleyenTahlilleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_BolumDoktorlariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_BolumDoktorlariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_BolumDoktorlariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","\n-- 4. sp_BolumDoktorlariGetir\nCREATE   PROCEDURE [dbo].[sp_BolumDoktorlariGetir]\n    @bolum_id INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT \n        k.kullanici_id,\n        k.ad_soyad AS DoktorAdi,\n        b.bolum_adi AS BolumAdi\n    FROM Doktorlar d \n    JOIN Kullanicilar k ON d.kullanici_ID = k.kullanici_id\n    JOIN Bolumler b ON d.bolum_ID = b.bolum_id\n    WHERE d.bolum_ID = @bolum_id\n    ORDER BY k.ad_soyad;\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_BolumDoktorlariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_BolumEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_BolumEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_BolumEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\n-- ==========================================\r\n-- 2. BÖLÜMLER\r\n-- ==========================================\r\nCREATE PROC [dbo].[sp_BolumEkle]\r\n@bolum_adi VARCHAR(100)\r\nAS\r\nBEGIN INSERT INTO Bolumler (bolum_adi) VALUES (@bolum_adi); END\r\n\r\n--EXEC sp_BolumEkle 'vvdsvdfsv'\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_BolumEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_BolumGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_BolumGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_BolumGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_BolumGuncelle] @bolum_id INT, @bolum_adi VARCHAR(100) AS\r\nBEGIN UPDATE Bolumler SET bolum_adi = @bolum_adi WHERE bolum_id = @bolum_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_BolumGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_BolumleriGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_BolumleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_BolumleriGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","\n-- 3. sp_BolumleriGetir\nCREATE   PROCEDURE [dbo].[sp_BolumleriGetir]\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT bolum_id, bolum_adi AS BolumAdi \n    FROM Bolumler \n    ORDER BY bolum_adi;\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_BolumleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_BolumSil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_BolumSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_BolumSil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_BolumSil] @bolum_id INT AS\r\nBEGIN DELETE FROM Bolumler WHERE bolum_id = @bolum_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_BolumSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_BosOdalariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_BosOdalariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_BosOdalariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- 2. Sadece Boş Odaları Getir (Yatış Verme Ekranındaki Liste İçin)\r\nCREATE   PROCEDURE [dbo].[sp_BosOdalariGetir]\r\nAS\r\nBEGIN\r\n    SELECT \r\n        oda_id, \r\n        'Oda ' + CAST(oda_id AS VARCHAR) + ' (Kapasite: ' + CAST(yatak_sayisi AS VARCHAR) + ')' AS [OdaAdi]\r\n    FROM Odalar\r\n    WHERE bos_mu = 1\r\n    ORDER BY oda_id ASC;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_BosOdalariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_DoktorAciklamasiKaydet]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorAciklamasiKaydet' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_DoktorAciklamasiKaydet]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE   PROCEDURE [dbo].[sp_DoktorAciklamasiKaydet] @sonuc_id INT, @doktor_aciklamasi NVARCHAR(MAX) AS BEGIN UPDATE TahlilSonuclari SET doktor_aciklamasi = @doktor_aciklamasi WHERE sonuc_id = @sonuc_id; END\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorAciklamasiKaydet' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_DoktorDashboard_GrafikBar]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorDashboard_GrafikBar' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_DoktorDashboard_GrafikBar]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- 2. SÜTUN GRAFİĞİ İÇİN (Haftalık Hasta Trafiği)\r\nCREATE   PROCEDURE [dbo].[sp_DoktorDashboard_GrafikBar]\r\n    @kullanici_id INT\r\nAS\r\nBEGIN\r\n    DECLARE @doktor_id INT = (SELECT TOP 1 doktor_id FROM Doktorlar WHERE kullanici_ID = @kullanici_id);\r\n    \r\n    SELECT TOP 7\r\n        FORMAT(randevu_tarihi, 'dd.MM') AS Gun,\r\n        COUNT(*) AS MuayeneSayisi\r\n    FROM Randevular\r\n    WHERE doktor_ID = @doktor_id \r\n    GROUP BY FORMAT(randevu_tarihi, 'dd.MM'), CAST(randevu_tarihi AS DATE)\r\n    ORDER BY CAST(randevu_tarihi AS DATE) ASC;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorDashboard_GrafikBar' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_DoktorDashboard_GrafikPie]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorDashboard_GrafikPie' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_DoktorDashboard_GrafikPie]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- 3. PASTA GRAFİĞİ İÇİN (Hasta Cinsiyet Dağılımı)\r\nCREATE   PROCEDURE [dbo].[sp_DoktorDashboard_GrafikPie]\r\n    @kullanici_id INT\r\nAS\r\nBEGIN\r\n    DECLARE @doktor_id INT = (SELECT TOP 1 doktor_id FROM Doktorlar WHERE kullanici_ID = @kullanici_id);\r\n    \r\n    SELECT \r\n        h.hastalar_cinsiyet AS Cinsiyet,\r\n        COUNT(DISTINCT r.hasta_ID) AS Sayi\r\n    FROM Randevular r\r\n    INNER JOIN Hastalar h ON r.hasta_ID = h.hasta_id\r\n    WHERE r.doktor_ID = @doktor_id\r\n    GROUP BY h.hastalar_cinsiyet;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorDashboard_GrafikPie' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_DoktorDashboard_Kartlar]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorDashboard_Kartlar' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_DoktorDashboard_Kartlar]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- 1. ÜSTTEKİ 4 KART İÇİN İSTATİSTİKLER (Tek Satırda Döner)\r\nCREATE   PROCEDURE [dbo].[sp_DoktorDashboard_Kartlar]\r\n    @kullanici_id INT\r\nAS\r\nBEGIN\r\n    DECLARE @doktor_id INT = (SELECT TOP 1 doktor_id FROM Doktorlar WHERE kullanici_ID = @kullanici_id);\r\n\r\n    DECLARE @ToplamHasta INT = (SELECT COUNT(DISTINCT hasta_ID) FROM Randevular WHERE doktor_ID = @doktor_id);\r\n    DECLARE @BugunRandevu INT = (SELECT COUNT(*) FROM Randevular WHERE doktor_ID = @doktor_id AND CAST(randevu_tarihi AS DATE) = CAST(GETDATE() AS DATE));\r\n    \r\n    DECLARE @DoluOda INT = (SELECT COUNT(*) FROM Odalar WHERE bos_mu = 0);\r\n    DECLARE @BosOda INT = (SELECT COUNT(*) FROM Odalar WHERE bos_mu = 1);\r\n    DECLARE @OdaDurum VARCHAR(20) = CAST(@DoluOda AS VARCHAR) + ' / ' + CAST(@BosOda AS VARCHAR);\r\n    \r\n    DECLARE @BekleyenTahlil INT = (SELECT COUNT(*) FROM TahlilSonuclari WHERE doktor_ID = @doktor_id AND (sonuc_degeri IS NULL OR sonuc_degeri = ''));\r\n\r\n    SELECT \r\n        ISNULL(@ToplamHasta, 0) AS ToplamHasta,\r\n        ISNULL(@BugunRandevu, 0) AS BugunRandevu,\r\n        ISNULL(@OdaDurum, '0 / 0') AS OdaDurum,\r\n        ISNULL(@BekleyenTahlil, 0) AS BekleyenTahlil;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorDashboard_Kartlar' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_DoktorDashboard_TabloBekleyen]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorDashboard_TabloBekleyen' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_DoktorDashboard_TabloBekleyen]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- 4. SOL TABLO: SIRADAKİ BEKLEYEN HASTALAR\r\nCREATE   PROCEDURE [dbo].[sp_DoktorDashboard_TabloBekleyen]\r\n    @kullanici_id INT\r\nAS\r\nBEGIN\r\n    DECLARE @doktor_id INT = (SELECT TOP 1 doktor_id FROM Doktorlar WHERE kullanici_ID = @kullanici_id);\r\n    \r\n    SELECT TOP 6\r\n        CONVERT(VARCHAR(5), r.randevu_tarihi, 108) AS [Saat],\r\n        h.hastalar_ad_soyad AS [Hasta Adı Soyadı],\r\n        ISNULL(r.sikayet, 'Belirtilmedi') AS [İşlem / Şikayet]\r\n    FROM Randevular r\r\n    INNER JOIN Hastalar h ON r.hasta_ID = h.hasta_id\r\n    WHERE r.doktor_ID = @doktor_id AND r.randevu_durum = 0\r\n    ORDER BY r.randevu_tarihi ASC;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorDashboard_TabloBekleyen' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_DoktorDashboard_TabloTahlil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorDashboard_TabloTahlil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_DoktorDashboard_TabloTahlil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- 5. SAĞ TABLO: SON ÇIKAN / BEKLEYEN TAHLİLLER\r\nCREATE   PROCEDURE [dbo].[sp_DoktorDashboard_TabloTahlil]\r\n    @kullanici_id INT\r\nAS\r\nBEGIN\r\n    DECLARE @doktor_id INT = (SELECT TOP 1 doktor_id FROM Doktorlar WHERE kullanici_ID = @kullanici_id);\r\n    \r\n    SELECT TOP 6\r\n        CONVERT(VARCHAR(10), ts.tahlil_sonuclari_tarih, 104) AS [Tarih],\r\n        h.hastalar_ad_soyad AS [Hasta Adı],\r\n        t.tahlil_adi AS [İstenen Tahlil]\r\n    FROM TahlilSonuclari ts\r\n    INNER JOIN Hastalar h ON ts.hasta_ID = h.hasta_id\r\n    INNER JOIN Tahliller t ON ts.tahlil_ID = t.tahlil_id\r\n    WHERE ts.doktor_ID = @doktor_id\r\n    ORDER BY ts.tahlil_sonuclari_tarih DESC;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorDashboard_TabloTahlil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_DoktorDashboardOzet]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorDashboardOzet' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_DoktorDashboardOzet]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_DoktorDashboardOzet]\r\nAS\r\nBEGIN\r\n    -- 1. Kartlar İçin Özet Sayılar\r\n    DECLARE @ToplamHasta INT = (SELECT COUNT(*) FROM Kullanicilar WHERE rol_ID = 2); -- Hasta rolü 2 varsayıldı\r\n    DECLARE @ToplamOda INT = (SELECT COUNT(*) FROM Odalar);\r\n    DECLARE @DoluOda INT = (SELECT COUNT(*) FROM Odalar WHERE bos_mu = 1); -- 1: Dolu varsayıldı\r\n    DECLARE @BekleyenTahlil INT = (SELECT COUNT(*) FROM TahlilSonuclari WHERE sonuc_degeri IS NULL);\r\n    \r\n    SELECT @ToplamHasta AS ToplamHasta, @ToplamOda AS ToplamOda, @DoluOda AS DoluOda, @BekleyenTahlil AS BekleyenTahlil;\r\n\r\n    -- 2. Grafik İçin Cinsiyet Dağılımı (Kullanicilar tablosunda cinsiyet varsa)\r\n    -- SELECT cinsiyet, COUNT(*) as Sayi FROM Kullanicilar WHERE rol_ID = 2 GROUP BY cinsiyet;\r\nEND\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorDashboardOzet' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_DoktorEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_DoktorEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROC [dbo].[sp_DoktorEkle] @kullanici_ID INT, @bolum_id INT, @uzmanlik_alani VARCHAR(100) AS\r\nBEGIN INSERT INTO Doktorlar (kullanici_ID, bolum_ID, uzmanlik_alani) VALUES (@kullanici_ID, @bolum_id, @uzmanlik_alani); END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_DoktorGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_DoktorGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_DoktorGuncelle] @doktor_id INT, @kullanici_ID INT, @bolum_id INT, @uzmanlik_alani VARCHAR(100) AS\r\nBEGIN UPDATE Doktorlar SET kullanici_ID = @kullanici_ID, bolum_ID = @bolum_id, uzmanlik_alani = @uzmanlik_alani WHERE doktor_id = @doktor_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_DoktorGunlukTakvim]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorGunlukTakvim' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_DoktorGunlukTakvim]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- 1. Günlük Randevular Tablosu İçin\r\nCREATE   PROCEDURE [dbo].[sp_DoktorGunlukTakvim]\r\n    @kullanici_id INT\r\nAS\r\nBEGIN\r\n    DECLARE @doktor_id INT = (SELECT TOP 1 doktor_id FROM Doktorlar WHERE kullanici_ID = @kullanici_id);\r\n    \r\n    SELECT \r\n        CONVERT(VARCHAR(5), r.randevu_tarihi, 108) AS [Saat],\r\n        h.hastalar_ad_soyad AS [Hasta Adı Soyadı],\r\n        ISNULL(r.sikayet, 'Belirtilmedi') AS [İşlem / Şikayet],\r\n        CASE WHEN r.randevu_durum = 1 THEN 'Tamamlandı' ELSE 'Bekliyor' END AS [Durum]\r\n    FROM Randevular r\r\n    INNER JOIN Hastalar h ON r.hasta_ID = h.hasta_id\r\n    WHERE r.doktor_ID = @doktor_id AND CAST(r.randevu_tarihi AS DATE) = CAST(GETDATE() AS DATE)\r\n    ORDER BY r.randevu_tarihi ASC;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorGunlukTakvim' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_DoktorHaftalikGrafik]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorHaftalikGrafik' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_DoktorHaftalikGrafik]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- 2. Haftalık Yoğunluk Grafiği İçin\r\nCREATE   PROCEDURE [dbo].[sp_DoktorHaftalikGrafik]\r\n    @kullanici_id INT\r\nAS\r\nBEGIN\r\n    DECLARE @doktor_id INT = (SELECT TOP 1 doktor_id FROM Doktorlar WHERE kullanici_ID = @kullanici_id);\r\n    \r\n    -- Son 7 günün randevu sayıları\r\n    SELECT TOP 7\r\n        FORMAT(randevu_tarihi, 'ddd') AS Gun, -- Pzt, Sal, Çar vb.\r\n        COUNT(*) AS RandevuSayisi\r\n    FROM Randevular\r\n    WHERE doktor_ID = @doktor_id \r\n          AND randevu_tarihi >= DATEADD(day, -7, GETDATE())\r\n    GROUP BY FORMAT(randevu_tarihi, 'ddd'), CAST(randevu_tarihi AS DATE)\r\n    ORDER BY CAST(randevu_tarihi AS DATE) ASC;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorHaftalikGrafik' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_DoktorlariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorlariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_DoktorlariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_DoktorlariGetir] AS\r\nBEGIN SELECT * FROM Doktorlar; END\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorlariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_DoktorSil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_DoktorSil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_DoktorSil] @doktor_id INT AS\r\nBEGIN DELETE FROM Doktorlar WHERE doktor_id = @doktor_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_DoktorTahlilSonuclariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorTahlilSonuclariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_DoktorTahlilSonuclariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE   PROCEDURE [dbo].[sp_DoktorTahlilSonuclariGetir] @kullanici_id INT AS BEGIN DECLARE @doktor_id INT = (SELECT TOP 1 doktor_id FROM Doktorlar WHERE kullanici_ID = @kullanici_id); SELECT ts.sonuc_id, CONVERT(VARCHAR(16), ts.tahlil_sonuclari_tarih, 120) AS [Tarih], h.hastalar_ad_soyad AS [Hasta Adı], t.tahlil_adi AS [İstenen Tahlil], ts.sonuc_degeri AS [Sonuç / Durum], ISNULL(t.referans_araligi, '') AS [Referans Aralığı], ISNULL(ts.doktor_aciklamasi, '') AS [Doktor Açıklaması] FROM TahlilSonuclari ts INNER JOIN Hastalar h ON ts.hasta_ID = h.hasta_id INNER JOIN Tahliller t ON ts.tahlil_ID = t.tahlil_id WHERE ts.doktor_ID = @doktor_id ORDER BY ts.tahlil_sonuclari_tarih DESC; END\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorTahlilSonuclariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_DoktorunHastalariniGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorunHastalariniGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_DoktorunHastalariniGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE   PROCEDURE [dbo].[sp_DoktorunHastalariniGetir]\r\n    @kullanici_id INT\r\nAS\r\nBEGIN\r\n    -- Kullanıcı ID'sinden Doktor ID'sini otomatik bulur\r\n    DECLARE @doktor_id INT = (SELECT TOP 1 doktor_id FROM Doktorlar WHERE kullanici_ID = @kullanici_id);\r\n    \r\n    -- Sadece o doktora ait randevusu olan hastaları getirir\r\n    SELECT DISTINCT h.hasta_id, h.hastalar_ad_soyad AS [HastaAdi]\r\n    FROM Randevular r\r\n    INNER JOIN Hastalar h ON r.hasta_ID = h.hasta_id\r\n    WHERE r.doktor_ID = @doktor_id;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_DoktorunHastalariniGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_FaturaEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_FaturaEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_FaturaEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROC [dbo].[sp_FaturaEkle] @faturalar_hasta_ID INT, @toplam_tutar DECIMAL(10,2), @fatura_tarihi DATE, @odendi_mi BIT AS\r\nBEGIN INSERT INTO Faturalar (hasta_ID, toplam_tutar, fatura_tarihi, odendi_mi) VALUES (@faturalar_hasta_ID, @toplam_tutar, @fatura_tarihi, @odendi_mi); END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_FaturaEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_FaturaGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_FaturaGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_FaturaGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_FaturaGuncelle] @fatura_ID INT, @faturalar_hasta_ID INT, @toplam_tutar DECIMAL(10,2), @fatura_tarihi DATE, @odendi_mi BIT AS\r\nBEGIN UPDATE Faturalar SET hasta_ID = @faturalar_hasta_ID, toplam_tutar = @toplam_tutar, fatura_tarihi = @fatura_tarihi, odendi_mi = @odendi_mi WHERE fatura_id = @fatura_ID; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_FaturaGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_FaturalariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_FaturalariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_FaturalariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","\n-- 13. sp_FaturalariGetir\nCREATE   PROCEDURE [dbo].[sp_FaturalariGetir]\n    @kullanici_id INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT \n        f.fatura_id AS [Fatura No],\n        CONVERT(NVARCHAR(10), f.fatura_tarihi, 103) AS [Tarih],\n        'Genel Sağlık Hizmeti' AS [Açıklama],\n        FORMAT(f.toplam_tutar, 'N2') + ' ₺' AS [Tutar],\n        CASE WHEN f.odendi_mi = 1 THEN 'Ödendi' ELSE 'Bekliyor' END AS [Durum]\n    FROM Faturalar f\n    JOIN Hastalar h ON f.hasta_ID = h.hasta_id\n    WHERE h.kullanici_ID = @kullanici_id\n    ORDER BY f.fatura_tarihi DESC;\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_FaturalariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_FaturaSil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_FaturaSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_FaturaSil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_FaturaSil] @fatura_ID INT AS\r\nBEGIN DELETE FROM Faturalar WHERE fatura_id = @fatura_ID; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_FaturaSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_GecmisMuayeneGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_GecmisMuayeneGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_GecmisMuayeneGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_GecmisMuayeneGuncelle]\r\n    @randevu_id INT,\r\n    @sikayet NVARCHAR(MAX),\r\n    @teshis NVARCHAR(MAX),\r\n    @notlar NVARCHAR(MAX)\r\nAS\r\nBEGIN\r\n    UPDATE Randevular \r\n    SET \r\n        sikayet = @sikayet,\r\n        teshis = @teshis,\r\n        notlar = @notlar\r\n    WHERE \r\n        randevu_id = @randevu_id;\r\nEND\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_GecmisMuayeneGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_GecmisMuayeneleriGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_GecmisMuayeneleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_GecmisMuayeneleriGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_GecmisMuayeneleriGetir] @kullanici_id INT AS BEGIN DECLARE @doktor_id INT = (SELECT TOP 1 doktor_id FROM Doktorlar WHERE kullanici_ID = @kullanici_id); SELECT r.randevu_id AS [Kayıt No], k.tc_no AS [TC Kimlik], h.hastalar_ad_soyad AS [Hasta Adı Soyadı], CONVERT(VARCHAR(16), r.randevu_tarihi, 120) AS [Randevu Zamanı], r.sikayet, r.teshis, r.notlar FROM Randevular r INNER JOIN Hastalar h ON r.hasta_ID = h.hasta_id INNER JOIN Kullanicilar k ON h.kullanici_ID = k.kullanici_id WHERE r.randevu_durum = 1 AND r.doktor_ID = @doktor_id ORDER BY r.randevu_tarihi DESC; END\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_GecmisMuayeneleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_HastaEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HastaEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_HastaEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\n-- ==========================================\r\n-- 5. HASTALAR\r\n-- ==========================================\r\nCREATE PROC [dbo].[sp_HastaEkle] @kullanici_ID VARCHAR(50), @hastalar_ad_soyad VARCHAR(100), @hastalar_dogum_tarih DATE, @hastalar_telefon VARCHAR(50), @hastalar_cinsiyet VARCHAR(50) AS\r\nBEGIN INSERT INTO Hastalar (kullanici_ID, hastalar_ad_soyad, hastalar_dogum_tarih, hastalar_telefon, hastalar_cinsiyet) VALUES (@kullanici_ID, @hastalar_ad_soyad, @hastalar_dogum_tarih, @hastalar_telefon, @hastalar_cinsiyet); END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HastaEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_HastaGecmisMuayeneleriGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HastaGecmisMuayeneleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_HastaGecmisMuayeneleriGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_HastaGecmisMuayeneleriGetir] @kullanici_id INT AS BEGIN SET NOCOUNT ON; SELECT r.randevu_id AS [Kayıt No], kd.ad_soyad AS [Doktor Adı], b.bolum_adi AS [Bölüm], CONVERT(NVARCHAR(16), r.randevu_tarihi, 120) AS [Randevu Zamanı], r.sikayet AS [Şikayet], r.teshis AS [Teşhis], r.notlar AS [Notlar] FROM Randevular r INNER JOIN Hastalar h ON r.hasta_ID = h.hasta_id INNER JOIN Doktorlar d ON r.doktor_ID = d.doktor_id INNER JOIN Kullanicilar kd ON d.kullanici_ID = kd.kullanici_id INNER JOIN Bolumler b ON d.bolum_ID = b.bolum_id WHERE r.randevu_durum = 1 AND h.kullanici_ID = @kullanici_id ORDER BY r.randevu_tarihi DESC; END\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HastaGecmisMuayeneleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_HastaGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HastaGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_HastaGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","\n-- 2. sp_HastaGuncelle\nCREATE   PROCEDURE [dbo].[sp_HastaGuncelle]\n    @kullanici_id  INT,\n    @telefon       NVARCHAR(20)  = NULL,\n    @email         NVARCHAR(100) = NULL,\n    @adres         NVARCHAR(300) = NULL,\n    @yeni_sifre    NVARCHAR(100) = NULL\nAS\nBEGIN\n    SET NOCOUNT ON;\n    UPDATE Hastalar \n    SET hastalar_telefon = ISNULL(@telefon, hastalar_telefon) \n    WHERE kullanici_ID = @kullanici_id;\n\n    IF @yeni_sifre IS NOT NULL\n    BEGIN\n        UPDATE Kullanicilar \n        SET sifre = @yeni_sifre \n        WHERE kullanici_id = @kullanici_id;\n    END\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HastaGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_HastaKaydol]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HastaKaydol' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_HastaKaydol]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- Ardından yenisini oluşturuyoruz\r\nCREATE PROCEDURE [dbo].[sp_HastaKaydol]\r\n    @ad_soyad VARCHAR(100),\r\n    @tc_no VARCHAR(11),\r\n    @sifre VARCHAR(50),\r\n    @telefon VARCHAR(15),\r\n    @dogum_tarihi DATE,\r\n    @cinsiyet VARCHAR(10)\r\nAS\r\nBEGIN\r\n    BEGIN TRY\r\n        BEGIN TRANSACTION;\r\n\r\n        -- 1. ADIM: Kullanıcılar tablosuna ekle (rol_ID 'Hasta' için 10)\r\n        INSERT INTO [dbo].[Kullanicilar] (ad_soyad, tc_no, sifre, rol_ID)\r\n        VALUES (@ad_soyad, @tc_no, @sifre, 10);\r\n\r\n        -- 2. ADIM: Eklenen kullanıcının ID'sini yakala\r\n        DECLARE @YenikullaniciID INT = SCOPE_IDENTITY();\r\n\r\n        -- 3. ADIM: Hastalar tablosuna detayları ekle\r\n        INSERT INTO [dbo].[Hastalar] (kullanici_ID, hastalar_ad_soyad, hastalar_dogum_tarih, hastalar_telefon, hastalar_cinsiyet)\r\n        VALUES (@YenikullaniciID, @ad_soyad, @dogum_tarihi, @telefon, @cinsiyet);\r\n\r\n        COMMIT TRANSACTION;\r\n    END TRY\r\n    BEGIN CATCH\r\n        ROLLBACK TRANSACTION;\r\n        THROW;\r\n    END CATCH\r\nEND\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HastaKaydol' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_HastalariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HastalariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_HastalariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_HastalariGetir] @kullanici_id INT AS BEGIN SET NOCOUNT ON; SELECT h.hastalar_ad_soyad AS AdSoyad, k.tc_no AS TCKimlik, CONVERT(NVARCHAR(10), h.hastalar_dogum_tarih, 103) AS DogumTarihi, h.hastalar_telefon AS Telefon, NULL AS Email, NULL AS Adres, h.kan_grubu AS KanGrubu, 'Hasta' AS rol FROM Hastalar h JOIN Kullanicilar k ON h.kullanici_ID = k.kullanici_id WHERE k.kullanici_id = @kullanici_id; END\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HastalariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_HastaSil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HastaSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_HastaSil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_HastaSil] @hasta_id INT AS\r\nBEGIN DELETE FROM Hastalar WHERE hasta_id = @hasta_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HastaSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_HastaYatisVer]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HastaYatisVer' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_HastaYatisVer]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- 3. Hastaya Yatış Ver ve Odayı Doldur\r\nCREATE   PROCEDURE [dbo].[sp_HastaYatisVer]\r\n    @hasta_id INT,\r\n    @oda_id INT\r\nAS\r\nBEGIN\r\n    -- 1. Yatislar tablosuna kaydet (Çıkış tarihi NULL kalır)\r\n    INSERT INTO Yatislar (hasta_ID, oda_ID, yatis_tarihi)\r\n    VALUES (@hasta_id, @oda_id, GETDATE());\r\n\r\n    -- 2. Odalar tablosunda odayı 'Dolu' (0) olarak işaretle\r\n    UPDATE Odalar SET bos_mu = 0 WHERE oda_id = @oda_id;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HastaYatisVer' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_HesapPasifeAl]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HesapPasifeAl' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_HesapPasifeAl]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROC [dbo].[sp_HesapPasifeAl] @kullanici_id INT AS BEGIN UPDATE Kullanicilar SET hesap_aktif_mi = 0 WHERE kullanici_id = @kullanici_id; INSERT INTO LogKayitlari (islem_tipi, aciklama, tarih) VALUES ('Hesap Otomatik Pasife Alındı', 'Kullanıcı 5 günden uzun süre giriş yapmadığı için sistem tarafından pasif konuma getirildi.', GETDATE()); END\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_HesapPasifeAl' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_IlacEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IlacEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_IlacEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\n-- ==========================================\r\n-- 9. İLAÇLAR\r\n-- ==========================================\r\nCREATE PROC [dbo].[sp_IlacEkle] @ilac_adi VARCHAR(100), @barkod VARCHAR(50) AS\r\nBEGIN INSERT INTO Ilaclar (ilac_adi, barkod) VALUES (@ilac_adi, @barkod); END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IlacEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_IlacGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IlacGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_IlacGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_IlacGuncelle] @ilac_ID INT, @ilac_adi VARCHAR(100), @barkod VARCHAR(50) AS\r\nBEGIN UPDATE Ilaclar SET ilac_adi = @ilac_adi, barkod = @barkod WHERE ilac_ID = @ilac_ID; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IlacGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_IlaclariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IlaclariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_IlaclariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- 1. İlaç Veritabanı İçin İlaçları Getir\r\nCREATE   PROCEDURE [dbo].[sp_IlaclariGetir]\r\nAS\r\nBEGIN\r\n    SELECT ilac_ID, ilac_adi AS [İlaç Adı], barkod AS [Barkod] FROM Ilaclar ORDER BY ilac_adi;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IlaclariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_IlacSil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IlacSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_IlacSil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_IlacSil] @ilac_ID INT AS\r\nBEGIN DELETE FROM Ilaclar WHERE ilac_ID = @ilac_ID; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IlacSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_IslemKaydiEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IslemKaydiEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_IslemKaydiEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\n-- ==========================================\r\n-- 16. İŞLEM KAYITLARI\r\n-- ==========================================\r\nCREATE PROC [dbo].[sp_IslemKaydiEkle] @kullanici_ID INT, @islem_tipi VARCHAR(100), @islem_tarihi DATE, @islem_kayitlari_aciklama VARCHAR(500) AS\r\nBEGIN INSERT INTO IslemKayitlari (kullanici_ID, islem_tipi, islem_tarihi, islem_kayitlari_aciklama) VALUES (@kullanici_ID, @islem_tipi, @islem_tarihi, @islem_kayitlari_aciklama); END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IslemKaydiEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_IslemKaydiGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IslemKaydiGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_IslemKaydiGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_IslemKaydiGuncelle] @log_id INT, @kullanici_ID INT, @islem_tipi VARCHAR(100), @islem_tarihi DATE, @islem_kayitlari_aciklama VARCHAR(500) AS\r\nBEGIN UPDATE IslemKayitlari SET kullanici_ID = @kullanici_ID, islem_tipi = @islem_tipi, islem_tarihi = @islem_tarihi, islem_kayitlari_aciklama = @islem_kayitlari_aciklama WHERE log_id = @log_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IslemKaydiGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_IslemKaydiSil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IslemKaydiSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_IslemKaydiSil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_IslemKaydiSil] @log_id INT AS\r\nBEGIN DELETE FROM IslemKayitlari WHERE log_id = @log_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IslemKaydiSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_IslemKayitlariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IslemKayitlariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_IslemKayitlariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","\n-- 10. sp_IslemKayitlariGetir\nCREATE   PROCEDURE [dbo].[sp_IslemKayitlariGetir]\n    @kullanici_id INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT \n        ik.log_id AS [İşlem No],\n        CONVERT(NVARCHAR(10), ik.islem_tarihi, 103) AS [Tarih],\n        '—' AS [Doktor],\n        ik.islem_tipi AS [Şikayet],\n        '—' AS [Teşhis],\n        ik.islem_kayitlari_aciklama AS [Notlar]\n    FROM IslemKayitlari ik\n    WHERE ik.kullanici_ID = @kullanici_id\n    ORDER BY ik.islem_tarihi DESC;\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_IslemKayitlariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_Istatistik_BolumSayisi]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_Istatistik_BolumSayisi' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_Istatistik_BolumSayisi]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_Istatistik_BolumSayisi] AS BEGIN SELECT COUNT(*) FROM Bolumler; END;\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_Istatistik_BolumSayisi' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_Istatistik_BolumYogunluklari]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_Istatistik_BolumYogunluklari' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_Istatistik_BolumYogunluklari]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE   PROCEDURE [dbo].[sp_Istatistik_BolumYogunluklari] AS BEGIN SELECT TOP 5 bolum_adi, COUNT(randevu_id) as RandevuSayisi FROM Bolumler b LEFT JOIN Doktorlar d ON b.bolum_id = d.bolum_ID LEFT JOIN Randevular r ON d.kullanici_ID = r.doktor_ID GROUP BY bolum_adi ORDER BY RandevuSayisi DESC; END;\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_Istatistik_BolumYogunluklari' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_Istatistik_BugunRandevu]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_Istatistik_BugunRandevu' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_Istatistik_BugunRandevu]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_Istatistik_BugunRandevu] AS BEGIN SELECT COUNT(*) FROM Randevular WHERE CAST(randevu_tarihi AS DATE) = CAST(GETDATE() AS DATE); END;\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_Istatistik_BugunRandevu' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_Istatistik_KullaniciSayisi]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_Istatistik_KullaniciSayisi' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_Istatistik_KullaniciSayisi]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_Istatistik_KullaniciSayisi] AS BEGIN SELECT COUNT(*) FROM Kullanicilar; END;\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_Istatistik_KullaniciSayisi' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_Istatistik_RandevuSayisi]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_Istatistik_RandevuSayisi' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_Istatistik_RandevuSayisi]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_Istatistik_RandevuSayisi] AS BEGIN SELECT COUNT(*) FROM Randevular; END;\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_Istatistik_RandevuSayisi' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_Istatistik_SonHareketler]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_Istatistik_SonHareketler' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_Istatistik_SonHareketler]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE   PROCEDURE [dbo].[sp_Istatistik_SonHareketler] AS BEGIN SELECT TOP 5 islem_tipi, islem_tarihi, islem_kayitlari_aciklama AS aciklama FROM IslemKayitlari ORDER BY log_id DESC; END;\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_Istatistik_SonHareketler' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_KullaniciEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullaniciEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_KullaniciEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROC [dbo].[sp_KullaniciEkle] @ad_soyad VARCHAR(100), @tc_no VARCHAR(50), @sifre VARCHAR(50), @rol_ID INT, @bolum_ID INT = NULL AS BEGIN INSERT INTO Kullanicilar (ad_soyad, tc_no, sifre, rol_ID, hesap_aktif_mi) VALUES (@ad_soyad, @tc_no, @sifre, @rol_ID, 1); DECLARE @yeni_kullanici_id INT = SCOPE_IDENTITY(); IF @rol_ID = 2 AND @bolum_ID IS NOT NULL BEGIN INSERT INTO Doktorlar (kullanici_ID, bolum_ID, uzmanlik_alani) VALUES (@yeni_kullanici_id, @bolum_ID, 'Genel'); END IF @rol_ID = 10 BEGIN INSERT INTO Hastalar (kullanici_ID, hastalar_ad_soyad, hastalar_dogum_tarih, hastalar_telefon, hastalar_cinsiyet) VALUES (@yeni_kullanici_id, @ad_soyad, '1990-01-01', '00000000000', 'Bilinmiyor'); END END\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullaniciEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_KullaniciGiris]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullaniciGiris' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_KullaniciGiris]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_KullaniciGiris] @tc_no NVARCHAR(11), @sifre NVARCHAR(50) AS BEGIN SELECT k.kullanici_id, k.rol_ID, k.ad_soyad, k.son_giris_tarihi, k.hesap_aktif_mi, (SELECT TOP 1 doktor_id FROM Doktorlar WHERE kullanici_ID = k.kullanici_id) AS doktor_id FROM Kullanicilar k WHERE k.tc_no = @tc_no AND k.sifre = @sifre; END\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullaniciGiris' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_KullaniciGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullaniciGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_KullaniciGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROC [dbo].[sp_KullaniciGuncelle] @kullanici_id INT, @ad_soyad VARCHAR(100), @tc_no VARCHAR(50), @sifre VARCHAR(50), @rol_ID INT, @hesap_aktif_mi BIT AS BEGIN UPDATE Kullanicilar SET ad_soyad = @ad_soyad, tc_no = @tc_no, sifre = @sifre, rol_ID = @rol_ID, hesap_aktif_mi = @hesap_aktif_mi WHERE kullanici_id = @kullanici_id; END\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullaniciGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_KullaniciIdGetirByTc]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullaniciIdGetirByTc' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_KullaniciIdGetirByTc]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_KullaniciIdGetirByTc] @tc_no varchar(50) AS BEGIN SELECT kullanici_id FROM Kullanicilar WHERE tc_no = @tc_no; END;\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullaniciIdGetirByTc' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_KullanicilariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullanicilariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_KullanicilariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_KullanicilariGetir] AS\r\nBEGIN SELECT * FROM Kullanicilar; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullanicilariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_KullaniciSil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullaniciSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_KullaniciSil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROC [dbo].[sp_KullaniciSil] @kullanici_id INT AS\nBEGIN\n    SET NOCOUNT ON;\n\n    DECLARE @doktor_id INT;\n    SELECT @doktor_id = doktor_id FROM Doktorlar WHERE kullanici_ID = @kullanici_id;\n\n    DECLARE @hasta_id INT;\n    SELECT @hasta_id = hasta_id FROM Hastalar WHERE kullanici_ID = @kullanici_id;\n\n    BEGIN TRY\n        BEGIN TRAN;\n\n        -- 1. Temel loglar ve kayitlar\n        DELETE FROM Loglar WHERE kullanici_id = @kullanici_id;\n        DELETE FROM IslemKayitlari WHERE kullanici_ID = @kullanici_id;\n        DELETE FROM DoktorBilgileri WHERE kullanici_id = @kullanici_id;\n\n        -- 2. Hasta ise bagli tablolari temizle\n        IF @hasta_id IS NOT NULL\n        BEGIN\n            DELETE FROM Odemeler WHERE fatura_ID IN (SELECT fatura_id FROM Faturalar WHERE hasta_ID = @hasta_id);\n            DELETE FROM Faturalar WHERE hasta_ID = @hasta_id;\n            \n            DELETE FROM ReceteDetaylari WHERE recete_ID IN (SELECT recete_id FROM Receteler WHERE hasta_ID = @hasta_id);\n            DELETE FROM ReceteIlaclari WHERE recete_id IN (SELECT recete_id FROM Receteler WHERE hasta_ID = @hasta_id);\n            DELETE FROM Receteler WHERE hasta_ID = @hasta_id;\n            \n            DELETE FROM TahlilSonuclari WHERE hasta_ID = @hasta_id;\n            DELETE FROM Yatislar WHERE hasta_ID = @hasta_id;\n            DELETE FROM Randevular WHERE hasta_ID = @hasta_id;\n            \n            DELETE FROM Hastalar WHERE hasta_id = @hasta_id;\n        END\n\n        -- 3. Doktor ise bagli tablolari temizle\n        IF @doktor_id IS NOT NULL\n        BEGIN\n            DELETE FROM ReceteDetaylari WHERE recete_ID IN (SELECT recete_id FROM Receteler WHERE doktor_ID = @doktor_id);\n            DELETE FROM ReceteIlaclari WHERE recete_id IN (SELECT recete_id FROM Receteler WHERE doktor_ID = @doktor_id);\n            DELETE FROM Receteler WHERE doktor_ID = @doktor_id;\n            \n            DELETE FROM TahlilSonuclari WHERE doktor_ID = @doktor_id;\n            DELETE FROM Randevular WHERE doktor_ID = @doktor_id;\n            \n            DELETE FROM Doktorlar WHERE doktor_id = @doktor_id;\n        END\n\n        -- 4. En son kullaniciyi sil\n        DELETE FROM Kullanicilar WHERE kullanici_id = @kullanici_id;\n\n        COMMIT TRAN;\n    END TRY\n    BEGIN CATCH\n        IF @@TRANCOUNT > 0 ROLLBACK TRAN;\n        THROW;\n    END CATCH\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullaniciSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_KullaniciSonGirisGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullaniciSonGirisGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_KullaniciSonGirisGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROC [dbo].[sp_KullaniciSonGirisGuncelle] @kullanici_id INT AS BEGIN UPDATE Kullanicilar SET son_giris_tarihi = GETDATE() WHERE kullanici_id = @kullanici_id; END\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullaniciSonGirisGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_KullaniciYetkiGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullaniciYetkiGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_KullaniciYetkiGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_KullaniciYetkiGuncelle] @tc_no varchar(50), @rol_ID int AS BEGIN UPDATE Kullanicilar SET rol_ID = @rol_ID WHERE tc_no = @tc_no; END;\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_KullaniciYetkiGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_LaborantGenelBakisHaftalikGidisat]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_LaborantGenelBakisHaftalikGidisat' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_LaborantGenelBakisHaftalikGidisat]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","\n-- 3. Haftalik Gidisat (Sütun Grafik)\nCREATE PROCEDURE [dbo].[sp_LaborantGenelBakisHaftalikGidisat]\nAS\nBEGIN\n    SELECT TOP 7\n        CAST(tahlil_sonuclari_tarih AS DATE) AS Tarih,\n        COUNT(sonuc_id) AS IslemSayisi\n    FROM TahlilSonuclari\n    GROUP BY CAST(tahlil_sonuclari_tarih AS DATE)\n    ORDER BY Tarih DESC\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_LaborantGenelBakisHaftalikGidisat' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_LaborantGenelBakisOzet]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_LaborantGenelBakisOzet' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_LaborantGenelBakisOzet]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","\n-- 1. Ozet Bilgiler\nCREATE PROCEDURE [dbo].[sp_LaborantGenelBakisOzet]\nAS\nBEGIN\n    SELECT \n        (SELECT COUNT(*) FROM TahlilSonuclari WHERE sonuc_degeri = 'Sonuç Bekleniyor...') AS BekleyenSayisi,\n        (SELECT COUNT(*) FROM TahlilSonuclari WHERE sonuc_degeri != 'Sonuç Bekleniyor...' AND CAST(tahlil_sonuclari_tarih AS DATE) = CAST(GETDATE() AS DATE)) AS BugunTamamlanan,\n        (SELECT COUNT(*) FROM TahlilSonuclari WHERE sonuc_degeri != 'Sonuç Bekleniyor...') AS ToplamTamamlanan\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_LaborantGenelBakisOzet' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_LaborantGenelBakisTahlilDagilimi]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_LaborantGenelBakisTahlilDagilimi' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_LaborantGenelBakisTahlilDagilimi]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","\n-- 2. Tahlil Dagilimi (Pasta Grafik)\nCREATE PROCEDURE [dbo].[sp_LaborantGenelBakisTahlilDagilimi]\nAS\nBEGIN\n    SELECT \n        t.tahlil_adi AS TahlilTuru,\n        COUNT(ts.sonuc_id) AS Miktar\n    FROM TahlilSonuclari ts\n    JOIN Tahliller t ON ts.tahlil_ID = t.tahlil_id\n    GROUP BY t.tahlil_adi\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_LaborantGenelBakisTahlilDagilimi' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_LogEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_LogEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_LogEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE   PROCEDURE [dbo].[sp_LogEkle] @kullanici_id INT = NULL, @islem_tipi NVARCHAR(50), @aciklama NVARCHAR(500) AS BEGIN SET NOCOUNT ON; INSERT INTO IslemKayitlari (kullanici_ID, islem_tipi, islem_tarihi, islem_kayitlari_aciklama) VALUES (@kullanici_id, @islem_tipi, GETDATE(), @aciklama); END;\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_LogEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_LoglariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_LoglariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_LoglariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE   PROCEDURE [dbo].[sp_LoglariGetir] AS BEGIN SET NOCOUNT ON; SELECT l.log_id AS [Kayıt No], FORMAT(l.islem_tarihi, 'dd.MM.yyyy HH:mm:ss') AS [Tarih], ISNULL(k.tc_no, 'SİSTEM') AS [TC Kimlik], ISNULL(k.ad_soyad, 'Misafir/Sistem') AS [Kullanıcı], r.rol_adi AS [Rol], l.islem_tipi AS [İşlem Tipi], l.islem_kayitlari_aciklama AS [Açıklama] FROM IslemKayitlari l LEFT JOIN Kullanicilar k ON l.kullanici_ID = k.kullanici_id LEFT JOIN Roller r ON k.rol_ID = r.rol_id ORDER BY l.log_id DESC; END;\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_LoglariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_MuayeneKaydet]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_MuayeneKaydet' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_MuayeneKaydet]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_MuayeneKaydet]\r\n    @randevu_id INT,\r\n    @sikayet NVARCHAR(MAX),\r\n    @teshis NVARCHAR(MAX),\r\n    @notlar NVARCHAR(MAX)\r\nAS\r\nBEGIN\r\n    -- Hem randevu durumunu 'Tamamlandı' (1) yapıyoruz, \r\n    -- Hem de C# formundan gelen metinleri tabloya kaydediyoruz!\r\n    UPDATE Randevular \r\n    SET \r\n        randevu_durum = 1,\r\n        sikayet = @sikayet,\r\n        teshis = @teshis,\r\n        notlar = @notlar\r\n    WHERE \r\n        randevu_id = @randevu_id;\r\nEND\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_MuayeneKaydet' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_OdaDurumlariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdaDurumlariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_OdaDurumlariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- 1. Tüm Odaların Durumunu Getir (Oda Durumları Ekranı İçin)\r\nCREATE   PROCEDURE [dbo].[sp_OdaDurumlariGetir]\r\nAS\r\nBEGIN\r\n    SELECT \r\n        oda_id AS [Oda No],\r\n        yatak_sayisi AS [Kapasite],\r\n        CASE WHEN bos_mu = 1 THEN 'Boş' ELSE 'Dolu' END AS [Mevcut Durum]\r\n    FROM Odalar\r\n    ORDER BY oda_id ASC;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdaDurumlariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_OdaEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdaEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_OdaEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\n-- ==========================================\r\n-- 6. ODALAR\r\n-- ==========================================\r\nCREATE PROC [dbo].[sp_OdaEkle] @oda_numarasi VARCHAR(50), @yatak_sayisi INT, @bos_mu BIT AS\r\nBEGIN INSERT INTO Odalar (oda_numarasi, yatak_sayisi, bos_mu) VALUES (@oda_numarasi, @yatak_sayisi, @bos_mu); END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdaEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_OdaGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdaGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_OdaGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_OdaGuncelle] @oda_id INT, @oda_numarasi VARCHAR(50), @yatak_sayisi INT, @bos_mu BIT AS\r\nBEGIN UPDATE Odalar SET oda_numarasi = @oda_numarasi, yatak_sayisi = @yatak_sayisi, bos_mu = @bos_mu WHERE oda_id = @oda_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdaGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_OdalariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdalariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_OdalariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_OdalariGetir] AS\r\nBEGIN SELECT * FROM Odalar; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdalariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_OdaSil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdaSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_OdaSil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_OdaSil] @oda_id INT AS\r\nBEGIN DELETE FROM Odalar WHERE oda_id = @oda_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdaSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_OdemeEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdemeEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_OdemeEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROC [dbo].[sp_OdemeEkle] @fatura_id INT, @odenen_miktar DECIMAL(10,2), @odeme_tarihi DATETIME, @odemeler_aciklama VARCHAR(255) AS\r\nBEGIN INSERT INTO Odemeler (fatura_ID, odenen_miktar, odeme_tarihi, odemeler_aciklama) VALUES (@fatura_id, @odenen_miktar, @odeme_tarihi, @odemeler_aciklama); END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdemeEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_OdemeGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdemeGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_OdemeGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_OdemeGuncelle] @odeme_id INT, @fatura_id INT, @odenen_miktar DECIMAL(10,2), @odeme_tarihi DATETIME, @odemeler_aciklama VARCHAR(255) AS\r\nBEGIN UPDATE Odemeler SET fatura_ID = @fatura_id, odenen_miktar = @odenen_miktar, odeme_tarihi = @odeme_tarihi, odemeler_aciklama = @odemeler_aciklama WHERE odeme_id = @odeme_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdemeGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_OdemeleriGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdemeleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_OdemeleriGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","\n-- 14. sp_OdemeleriGetir\nCREATE   PROCEDURE [dbo].[sp_OdemeleriGetir]\n    @kullanici_id INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT \n        o.odeme_id AS [Ödeme No],\n        CONVERT(NVARCHAR(16), o.odeme_tarihi, 120) AS [Tarih & Saat],\n        ISNULL(o.odemeler_aciklama, '—') AS [Fatura Açıklaması],\n        FORMAT(o.odenen_miktar, 'N2') + ' ₺' AS [Ödenen Tutar],\n        '—' AS [Ödeme Yöntemi]\n    FROM Odemeler o\n    JOIN Faturalar f ON o.fatura_ID = f.fatura_id\n    JOIN Hastalar h ON f.hasta_ID = h.hasta_id\n    WHERE h.kullanici_ID = @kullanici_id\n    ORDER BY o.odeme_tarihi DESC;\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdemeleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_OdemeSil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdemeSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_OdemeSil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_OdemeSil] @odeme_id INT AS\r\nBEGIN DELETE FROM Odemeler WHERE odeme_id = @odeme_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_OdemeSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_RandevuEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RandevuEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_RandevuEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_RandevuEkle] @hasta_id INT, @doktor_id INT, @randevu_tarihi DATETIME, @notlar NVARCHAR(MAX) = NULL AS BEGIN SET NOCOUNT ON; DECLARE @g_hasta_id INT, @g_doktor_id INT; SELECT @g_hasta_id = hasta_id FROM Hastalar WHERE kullanici_ID = @hasta_id; SELECT @g_doktor_id = doktor_id FROM Doktorlar WHERE kullanici_ID = @doktor_id; INSERT INTO Randevular (hasta_ID, doktor_ID, randevu_tarihi, randevu_durum, notlar) VALUES (@g_hasta_id, @g_doktor_id, @randevu_tarihi, 0, @notlar); END\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RandevuEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_RandevuGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RandevuGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_RandevuGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_RandevuGuncelle] @randevu_id INT, @hasta_ID INT, @doktor_ID INT, @randevu_tarihi DATETIME, @randevu_durum VARCHAR(50) AS\r\nBEGIN UPDATE Randevular SET hasta_ID = @hasta_ID, doktor_ID = @doktor_ID, randevu_tarihi = @randevu_tarihi, randevu_durum = @randevu_durum WHERE randevu_id = @randevu_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RandevuGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_RandevulariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RandevulariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_RandevulariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_RandevulariGetir] @kullanici_id INT AS BEGIN SET NOCOUNT ON; SELECT r.randevu_id AS [Randevu No], kd.ad_soyad AS [Doktor Adı], b.bolum_adi AS [Bölüm], CONVERT(NVARCHAR(16), r.randevu_tarihi, 120) AS [Tarih & Saat], CASE WHEN r.randevu_durum = 0 THEN 'Bekliyor' WHEN r.randevu_durum = 1 THEN 'Tamamlandı' WHEN r.randevu_durum = 2 THEN 'İptal Edildi' ELSE 'Bilinmiyor' END AS [Durum], ISNULL(r.notlar, '—') AS [Notlar] FROM Randevular r JOIN Hastalar h ON r.hasta_ID = h.hasta_id JOIN Doktorlar d ON r.doktor_ID = d.doktor_id JOIN Kullanicilar kd ON d.kullanici_ID = kd.kullanici_id JOIN Bolumler b ON d.bolum_ID = b.bolum_id WHERE h.kullanici_ID = @kullanici_id ORDER BY r.randevu_tarihi DESC; END\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RandevulariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_RandevuSil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RandevuSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_RandevuSil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","\n-- 7. sp_RandevuSil\nCREATE   PROCEDURE [dbo].[sp_RandevuSil]\n    @randevu_id INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    UPDATE Randevular \n    SET randevu_durum = 0 \n    WHERE randevu_id = @randevu_id;\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RandevuSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ReceteBaslikEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteBaslikEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_ReceteBaslikEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- 3. Reçeteyi Veritabanına Kaydet (Başlık)\r\nCREATE   PROCEDURE [dbo].[sp_ReceteBaslikEkle]\r\n    @hasta_id INT,\r\n    @kullanici_id INT,\r\n    @tani NVARCHAR(255)\r\nAS\r\nBEGIN\r\n    DECLARE @doktor_id INT = (SELECT TOP 1 doktor_id FROM Doktorlar WHERE kullanici_ID = @kullanici_id);\r\n    \r\n    INSERT INTO Receteler (hasta_ID, doktor_ID, receteler_tarih, tani)\r\n    VALUES (@hasta_id, @doktor_id, GETDATE(), @tani);\r\n    \r\n    -- Eklenen yeni reçetenin ID'sini C#'a döndürür\r\n    SELECT SCOPE_IDENTITY() AS YeniReceteID; \r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteBaslikEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ReceteDetayEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteDetayEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_ReceteDetayEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- 4. Reçeteye İlaçları Ekle (Detaylar)\r\nCREATE   PROCEDURE [dbo].[sp_ReceteDetayEkle]\r\n    @recete_id INT,\r\n    @ilac_id INT,\r\n    @kullanim_sekli NVARCHAR(255)\r\nAS\r\nBEGIN\r\n    INSERT INTO ReceteDetaylari (recete_ID, ilac_ID, kullanim_sekli)\r\n    VALUES (@recete_id, @ilac_id, @kullanim_sekli);\r\n    \r\n    SELECT 1 AS Sonuc; -- SqlHelper'ın hata vermemesi için dummy dönüş\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteDetayEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ReceteDetayGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteDetayGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_ReceteDetayGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_ReceteDetayGuncelle] @detay_id INT, @recete_ID INT, @ilac_ID INT, @kullanim_sekli VARCHAR(100) AS\r\nBEGIN UPDATE ReceteDetaylari SET recete_ID = @recete_ID, ilac_ID = @ilac_ID, kullanim_sekli = @kullanim_sekli WHERE detay_id = @detay_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteDetayGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ReceteDetaylariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteDetaylariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_ReceteDetaylariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_ReceteDetaylariGetir] AS\r\nBEGIN SELECT * FROM ReceteDetaylari; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteDetaylariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ReceteDetaySil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteDetaySil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_ReceteDetaySil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_ReceteDetaySil] @detay_id INT AS\r\nBEGIN DELETE FROM ReceteDetaylari WHERE detay_id = @detay_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteDetaySil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ReceteEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_ReceteEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\n-- ==========================================\r\n-- 10. REÇETELER\r\n-- ==========================================\r\nCREATE PROC [dbo].[sp_ReceteEkle] @hasta_ID INT, @doktor_ID INT, @receteler_tarih DATETIME, @tani VARCHAR(50) AS\r\nBEGIN INSERT INTO Receteler (hasta_ID, doktor_ID, receteler_tarih, tani) VALUES (@hasta_ID, @doktor_ID, @receteler_tarih, @tani); END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ReceteGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_ReceteGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_ReceteGuncelle] @recete_id INT, @hasta_ID INT, @doktor_ID INT, @receteler_tarih DATETIME, @tani VARCHAR(50) AS\r\nBEGIN UPDATE Receteler SET hasta_ID = @hasta_ID, doktor_ID = @doktor_ID, receteler_tarih = @receteler_tarih, tani = @tani WHERE recete_id = @recete_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ReceteleriGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_ReceteleriGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\nCREATE   PROCEDURE [dbo].[sp_ReceteleriGetir]\n    @kullanici_id INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT \n        r.recete_id AS [Reçete No],\n        CONVERT(NVARCHAR(10), r.receteler_tarih, 103) AS [Tarih],\n        kd.ad_soyad AS [Yazan Doktor],\n        ISNULL(\n            STUFF((\n                SELECT ', ' + i.ilac_adi + ' (' + ISNULL(rd.kullanim_sekli, '—') + ')'\n                FROM ReceteDetaylari rd \n                JOIN Ilaclar i ON rd.ilac_ID = i.ilac_ID\n                WHERE rd.recete_ID = r.recete_id\n                FOR XML PATH(''), TYPE\n            ).value('.', 'NVARCHAR(MAX)'), 1, 2, ''),\n        '—') AS [İlaçlar]\n    FROM Receteler r\n    JOIN Hastalar h ON r.hasta_ID = h.hasta_id\n    JOIN Doktorlar d ON r.doktor_ID = d.doktor_id\n    JOIN Kullanicilar kd ON d.kullanici_ID = kd.kullanici_id\n    WHERE h.kullanici_ID = @kullanici_id\n    ORDER BY r.receteler_tarih DESC;\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ReceteSil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_ReceteSil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_ReceteSil] @recete_id INT AS\r\nBEGIN DELETE FROM Receteler WHERE recete_id = @recete_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_ReceteSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_RolEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RolEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_RolEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROC [dbo].[sp_RolEkle] @rol_adi VARCHAR(50) AS\r\nBEGIN INSERT INTO Roller (rol_adi) VALUES (@rol_adi); END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RolEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_RolGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RolGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_RolGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_RolGuncelle] @rol_ID INT, @rol_adi VARCHAR(50) AS\r\nBEGIN UPDATE Roller SET rol_adi = @rol_adi WHERE rol_id = @rol_ID; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RolGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_RolleriGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RolleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_RolleriGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_RolleriGetir] AS\r\nBEGIN SELECT * FROM Roller; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RolleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_RolSil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RolSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_RolSil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_RolSil] @rol_ID INT AS\r\nBEGIN DELETE FROM Roller WHERE rol_id = @rol_ID; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_RolSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_SistemTahlilleriniGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_SistemTahlilleriniGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_SistemTahlilleriniGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","-- 1. Tüm Tahlil Türlerini Getir (Combobox için)\r\nCREATE   PROCEDURE [dbo].[sp_SistemTahlilleriniGetir]\r\nAS\r\nBEGIN\r\n    SELECT tahlil_id, tahlil_adi AS [Tahlil Adı] FROM Tahliller ORDER BY tahlil_adi;\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_SistemTahlilleriniGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_TahlilEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_TahlilEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\n-- ==========================================\r\n-- 12. TAHLİLLER\r\n-- ==========================================\r\nCREATE PROC [dbo].[sp_TahlilEkle] @tahlil_adi VARCHAR(100), @birim_fiyati DECIMAL(10,2) AS\r\nBEGIN INSERT INTO Tahliller (tahlil_adi, birim_fiyati) VALUES (@tahlil_adi, @birim_fiyati); END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_TahlilGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_TahlilGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_TahlilGuncelle] @tahlil_id INT, @tahlil_adi VARCHAR(100), @birim_fiyati DECIMAL(10,2) AS\r\nBEGIN UPDATE Tahliller SET tahlil_adi = @tahlil_adi, birim_fiyati = @birim_fiyati WHERE tahlil_id = @tahlil_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_TahlilKaydet]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilKaydet' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_TahlilKaydet]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- 2. Tahlil İsteğini Veritabanına Kaydet\r\nCREATE   PROCEDURE [dbo].[sp_TahlilKaydet]\r\n    @hasta_id INT,\r\n    @kullanici_id INT,\r\n    @tahlil_id INT\r\nAS\r\nBEGIN\r\n    DECLARE @doktor_id INT = (SELECT TOP 1 doktor_id FROM Doktorlar WHERE kullanici_ID = @kullanici_id);\r\n    \r\n    -- Tahlil ilk istendiğinde sonucu 'Bekliyor' olarak kaydedilir\r\n    INSERT INTO TahlilSonuclari (hasta_ID, tahlil_ID, tahlil_sonuclari_tarih, doktor_ID, sonuc_degeri)\r\n    VALUES (@hasta_id, @tahlil_id, GETDATE(), @doktor_id, 'Sonuç Bekleniyor...');\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilKaydet' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_TahlilleriGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_TahlilleriGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","\n-- 11. sp_TahlilleriGetir\nCREATE   PROCEDURE [dbo].[sp_TahlilleriGetir]\n    @kullanici_id INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT \n        ts.sonuc_id AS [Tahlil No],\n        t.tahlil_adi AS [Tahlil Adı],\n        kd.ad_soyad AS [İsteyen Doktor],\n        CONVERT(NVARCHAR(10), ts.tahlil_sonuclari_tarih, 103) AS [İstek Tarihi],\n        CASE WHEN ts.sonuc_degeri IS NULL THEN 'Bekliyor' ELSE 'Sonuçlandı' END AS [Durum],\n        1 AS [Sonuç Sayısı]\n    FROM TahlilSonuclari ts\n    JOIN Tahliller t ON ts.tahlil_ID = t.tahlil_id\n    JOIN Hastalar h ON ts.hasta_ID = h.hasta_id\n    LEFT JOIN Doktorlar d ON ts.doktor_ID = d.doktor_id\n    LEFT JOIN Kullanicilar kd ON d.kullanici_ID = kd.kullanici_id\n    WHERE h.kullanici_ID = @kullanici_id\n    ORDER BY ts.tahlil_sonuclari_tarih DESC;\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_TahlilSil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_TahlilSil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_TahlilSil] @tahlil_id INT AS\r\nBEGIN DELETE FROM Tahliller WHERE tahlil_id = @tahlil_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_TahlilSonucEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilSonucEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_TahlilSonucEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\n-- ==========================================\r\n-- 13. TAHLİL SONUÇLARI\r\n-- ==========================================\r\nCREATE PROC [dbo].[sp_TahlilSonucEkle] @hasta_ID INT, @tahlil_ID INT, @sonuc_degeri VARCHAR(200), @tahlil_sonuclari_tarih DATETIME, @doktor_ID INT AS\r\nBEGIN INSERT INTO TahlilSonuclari (hasta_ID, tahlil_ID, sonuc_degeri, tahlil_sonuclari_tarih, doktor_ID) VALUES (@hasta_ID, @tahlil_ID, @sonuc_degeri, @tahlil_sonuclari_tarih, @doktor_ID); END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilSonucEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_TahlilSonucGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilSonucGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_TahlilSonucGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_TahlilSonucGuncelle] @sonuc_id INT, @hasta_ID INT, @tahlil_ID INT, @sonuc_degeri VARCHAR(200), @tahlil_sonuclari_tarih DATETIME, @doktor_ID INT AS\r\nBEGIN UPDATE TahlilSonuclari SET hasta_ID = @hasta_ID, tahlil_ID = @tahlil_ID, sonuc_degeri = @sonuc_degeri, tahlil_sonuclari_tarih = @tahlil_sonuclari_tarih, doktor_ID = @doktor_ID WHERE sonuc_id = @sonuc_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilSonucGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_TahlilSonuclariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilSonuclariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_TahlilSonuclariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","\n-- 12. sp_TahlilSonuclariGetir\nCREATE   PROCEDURE [dbo].[sp_TahlilSonuclariGetir]\n    @kullanici_id INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT \n        ts.sonuc_id AS [Sonuç No],\n        t.tahlil_adi AS [Tahlil],\n        'Genel' AS [Parametre],\n        ISNULL(ts.sonuc_degeri, '—') AS [Ölçülen Değer],\n        '—' AS [Referans Aralığı],\n        '—' AS [Yorum],\n        CONVERT(NVARCHAR(10), ts.tahlil_sonuclari_tarih, 103) AS [Tarih]\n    FROM TahlilSonuclari ts\n    JOIN Tahliller t ON ts.tahlil_ID = t.tahlil_id\n    JOIN Hastalar h ON ts.hasta_ID = h.hasta_id\n    WHERE h.kullanici_ID = @kullanici_id\n    ORDER BY ts.tahlil_sonuclari_tarih DESC;\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilSonuclariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_TahlilSonucSil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilSonucSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_TahlilSonucSil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_TahlilSonucSil] @sonuc_id INT AS\r\nBEGIN DELETE FROM TahlilSonuclari WHERE sonuc_id = @sonuc_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilSonucSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_TahlilSonucuGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilSonucuGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_TahlilSonucuGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_TahlilSonucuGuncelle]\n    @sonuc_id INT,\n    @sonuc_degeri VARCHAR(MAX)\nAS\nBEGIN\n    UPDATE TahlilSonuclari\n    SET sonuc_degeri = @sonuc_degeri,\n        tahlil_sonuclari_tarih = GETDATE()\n    WHERE sonuc_id = @sonuc_id;\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TahlilSonucuGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_TamamlanmisTahlilleriGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TamamlanmisTahlilleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_TamamlanmisTahlilleriGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","\nCREATE PROCEDURE [dbo].[sp_TamamlanmisTahlilleriGetir]\nAS\nBEGIN\n    SELECT \n        ts.sonuc_id,\n        k.ad_soyad AS HastaAdi,\n        t.tahlil_adi AS TahlilAdi,\n        ts.tahlil_sonuclari_tarih AS IstenmeTarihi,\n        d_k.ad_soyad AS DoktorAdi,\n        t.referans_araligi AS ReferansAraligi,\n        ts.sonuc_degeri AS MevcutSonuc\n    FROM TahlilSonuclari ts\n    JOIN Kullanicilar k ON ts.hasta_ID = k.kullanici_id\n    JOIN Tahliller t ON ts.tahlil_ID = t.tahlil_id\n    JOIN Doktorlar d ON ts.doktor_ID = d.doktor_id\n    JOIN Kullanicilar d_k ON d.kullanici_ID = d_k.kullanici_id\n    WHERE ts.sonuc_degeri != 'Sonuç Bekleniyor...'\n    ORDER BY ts.tahlil_sonuclari_tarih DESC;\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_TamamlanmisTahlilleriGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_YatisEkle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_YatisEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_YatisEkle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n\r\n-- ==========================================\r\n-- 8. YATIŞLAR\r\n-- ==========================================\r\nCREATE PROC [dbo].[sp_YatisEkle] @hasta_ID INT, @oda_ID INT, @yatis_tarihi DATETIME, @cikis_tarihi DATETIME AS\r\nBEGIN INSERT INTO Yatislar (hasta_ID, oda_ID, yatis_tarihi, cikis_tarihi) VALUES (@hasta_ID, @oda_ID, @yatis_tarihi, @cikis_tarihi); END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_YatisEkle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_YatisGuncelle]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_YatisGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_YatisGuncelle]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_YatisGuncelle] @yatis_id INT, @hasta_ID INT, @oda_ID INT, @yatis_tarihi DATETIME, @cikis_tarihi DATETIME AS\r\nBEGIN UPDATE Yatislar SET hasta_ID = @hasta_ID, oda_ID = @oda_ID, yatis_tarihi = @yatis_tarihi, cikis_tarihi = @cikis_tarihi WHERE yatis_id = @yatis_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_YatisGuncelle' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_YatislariGetir]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_YatislariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_YatislariGetir]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER OFF\r\n","GO\r\n","\n-- 9. sp_YatislariGetir\nCREATE   PROCEDURE [dbo].[sp_YatislariGetir]\n    @kullanici_id INT\nAS\nBEGIN\n    SET NOCOUNT ON;\n    SELECT \n        y.yatis_id AS [Yatış No],\n        o.oda_numarasi AS [Oda],\n        '—' AS [Sorumlu Doktor],\n        CONVERT(NVARCHAR(10), y.yatis_tarihi, 103) AS [Giriş Tarihi],\n        ISNULL(CONVERT(NVARCHAR(10), y.cikis_tarihi, 103), 'Devam Ediyor') AS [Çıkış Tarihi],\n        CASE \n            WHEN y.cikis_tarihi IS NOT NULL THEN CAST(DATEDIFF(DAY, y.yatis_tarihi, y.cikis_tarihi) AS NVARCHAR) + ' gün'\n            ELSE CAST(DATEDIFF(DAY, y.yatis_tarihi, GETDATE()) AS NVARCHAR) + ' gün (devam ediyor)' \n        END AS [Süre],\n        CASE WHEN y.cikis_tarihi IS NULL THEN 'Aktif' ELSE 'Taburcu' END AS [Durum]\n    FROM Yatislar y\n    JOIN Hastalar h ON y.hasta_ID = h.hasta_id\n    JOIN Odalar o ON y.oda_ID = o.oda_id\n    WHERE h.kullanici_ID = @kullanici_id\n    ORDER BY y.yatis_tarihi DESC;\nEND\n\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_YatislariGetir' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_YatisSil]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_YatisSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_YatisSil]    Script Date: 25.08.2026 09:18:27 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\nCREATE PROC [dbo].[sp_YatisSil] @yatis_id INT AS\r\nBEGIN DELETE FROM Yatislar WHERE yatis_id = @yatis_id; END\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']/StoredProcedure[@Name='sp_YatisSil' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [HASTANEYONETIM_DB]"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']","object_type":"Database"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["USE [master]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']","object_type":"Database"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["ALTER DATABASE [HASTANEYONETIM_DB] SET  READ_WRITE \r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='DESKTOP-4B27P5S']/Database[@Name='HASTANEYONETIM_DB']","object_type":"Database"}}]}